//! Bounded resource-discovery research copilot for Worldgen P05 F09-F12.
use std::collections::BTreeSet;
use super::resource_discovery_support::{self,ResourceDiscoveryRequest,ResourceDiscoveryReceipt};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.resource-copilot-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ResourceCopilotRequest{pub discovery:ResourceDiscoveryRequest,pub action_order:Vec<String>,pub action_budget:u64,pub dry_run:bool,pub signed_approval:bool,pub federation_approved:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ResourceCopilotReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub need_id:String,pub disposition:String,pub action_order:Vec<String>,pub admitted_action_order:Vec<String>,pub denied_action_order:Vec<String>,pub discovery_disposition:String,pub discovery_digest:ContentHash,pub copilot_digest:ContentHash,pub replay_identity:ContentHash,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ResourceCopilotError{#[error("invalid resource copilot request: {0}")]Invalid(String),#[error("resource discovery failed: {0}")]Discovery(String),#[error("resource copilot artifact failed: {0}")]Artifact(String),#[error("invalid resource copilot receipt: {0}")]Receipt(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn s(v:Vec<String>)->Vec<String>{let mut o=v;o.sort();o.dedup();o}
impl ResourceCopilotReceipt{pub fn validate(&self)->Result<(),ResourceCopilotError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.need_id.trim().is_empty()||self.action_order.is_empty()||self.effect_receipts.is_empty()||![&self.discovery_digest,&self.copilot_digest,&self.replay_identity].into_iter().all(h){return Err(ResourceCopilotError::Receipt("resource copilot identity, actions, locality, digests, or effects are incomplete".into()));}for v in [&self.action_order,&self.admitted_action_order,&self.denied_action_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(ResourceCopilotError::Receipt("resource copilot vectors are not canonical".into()));}}let actions=self.action_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.admitted_action_order.iter().chain(&self.denied_action_order).cloned().collect::<Vec<_>>();if actions.len()!=self.action_order.len()||parts.len()!=actions.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=actions{return Err(ResourceCopilotError::Receipt("resource copilot actions do not partition".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.copilot_digest.as_str()){return Err(ResourceCopilotError::Receipt("resource copilot artifact digest is inconsistent".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["resource steward","preclinical researcher","workflow operator"],"behavior":format!("run bounded resource-discovery actions for {scale}"),"value":"turns ranked resources into an approval-bounded product without exposing protected resources","input_schema":input_schema,"output_schema":"ResourceCopilotReceipt1@1","effects":["invoke:bounded-resource-tool","block:unsafe-release"],"permissions":["invoke:declared-resource-tool"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn run(request:&ResourceCopilotRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool,require_federation:bool)->Result<ResourceCopilotReceipt,ResourceCopilotError>{if request.boundary!=PRECLINICAL_BOUNDARY||request.action_order.is_empty()||request.action_budget==0||request.action_order!=s(request.action_order.clone())||!request.discovery.raw_data_local||!request.discovery.aggregate_only{return Err(ResourceCopilotError::Invalid("resource copilot boundary, action, budget, locality, or ordering is invalid".into()));}let discovery=resource_discovery_support::discover(&request.discovery,feature_id,version,scale,require_federation).map_err(|e|ResourceCopilotError::Discovery(e.to_string()))?;let mut omissions=discovery.omissions.clone();let approved=(!require_approval||request.signed_approval)&&(!require_federation||request.federation_approved);if !approved{omissions.push("copilot:approval-missing".into());}if request.dry_run{omissions.push("copilot:dry-run-no-effect".into());}if request.action_order.len()as u64>request.action_budget{omissions.push("copilot:action-budget-exceeded".into());}let safe=discovery.disposition=="qualified"&&approved&&request.action_order.len()as u64<=request.action_budget;let disposition=if safe{"qualified"}else if discovery.disposition=="blocked"||!approved{"blocked"}else{"partial"};let admitted=if safe{request.action_order.clone()}else{Vec::new()};let denied=if safe{Vec::new()}else{request.action_order.clone()};let effects=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("invoke:bounded-resource-tool:{}",request.discovery.need_id)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"need_id":request.discovery.need_id,"disposition":disposition,"action_order":request.action_order,"admitted_action_order":admitted,"denied_action_order":denied,"discovery_disposition":discovery.disposition,"discovery_digest":discovery.discovery_digest,"replay_identity":discovery.replay_identity,"omissions":s(omissions),"uncertainty":discovery.uncertainty,"negative_evidence":discovery.negative_evidence,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|ResourceCopilotError::Artifact(e.to_string()))?;let r=ResourceCopilotReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),need_id:request.discovery.need_id.clone(),disposition:disposition.into(),action_order:request.action_order.clone(),admitted_action_order:admitted,denied_action_order:denied,discovery_disposition:discovery.disposition,discovery_digest:discovery.discovery_digest,copilot_digest:d.clone(),replay_identity:discovery.replay_identity,omissions:s(payload["omissions"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect()),uncertainty:discovery.uncertainty,negative_evidence:discovery.negative_evidence,effect_receipts:effects,artifact:json!({"artifact_id":format!("resource-copilot:{}",request.discovery.need_id),"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};r.validate()?;Ok(r)}

